package br.edu.diaw.locadora;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.server.ResponseStatusException;import java.util.*;import java.time.LocalDate;import java.math.BigDecimal;
@RestController @RequestMapping("/api") public class ApiController {
 private final AccountRepository users;private final CarRepository cars;private final RentalRepository rentals;private final CreditRepository credits;private final PasswordEncoder encoder;
 public ApiController(AccountRepository u,CarRepository c,RentalRepository r,CreditRepository cr,PasswordEncoder e){users=u;cars=c;rentals=r;credits=cr;encoder=e;}
 public record IncomePayload(String employer,BigDecimal monthlyAmount){}
 public record AccountPayload(String username,String password,String name,String cpf,String rg,String address,String profession,List<IncomePayload> incomes){}
 public record Profile(Long id,String username,String role,String name,String cpf,String rg,String address,String profession,List<IncomePayload> incomes){}
 public record RentalPayload(Long carId,LocalDate startDate,LocalDate endDate){}
 public record ReviewPayload(String status,String financialOpinion){}
 public record CreditPayload(Long bankId,BigDecimal amount,int installments){}
 public record RentalView(Long id,Car car,LocalDate startDate,LocalDate endDate,String status,String financialOpinion,String clientName,String reviewedBy){}
 private Account current(Authentication auth){return users.findByUsernameIgnoreCase(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 private boolean agent(Account a){return "AGENT".equals(a.role);}
 private void requireClient(Account a){if(agent(a))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Somente clientes");}
 private void checkDates(LocalDate start,LocalDate end){if(start==null||end==null||start.isBefore(LocalDate.now())||end.isBefore(start))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Período inválido");}
 private Profile profile(Account a){return new Profile(a.id,a.username,a.role,a.name,a.cpf,a.rg,a.address,a.profession,a.incomes.stream().map(i->new IncomePayload(i.employer,i.monthlyAmount)).toList());}
 private RentalView view(Rental r){return new RentalView(r.id,r.car,r.startDate,r.endDate,r.status.name(),r.financialOpinion,r.client.name,r.reviewedBy);}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","ok","system","VOLANTE");}
 @PostMapping("/auth/register") public ResponseEntity<?> register(@RequestBody AccountPayload p){if(p.username()==null||p.username().isBlank()||p.password()==null||p.password().length()<6||p.name()==null||p.name().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nome, usuário e senha (6+ caracteres) são obrigatórios");if(users.findByUsernameIgnoreCase(p.username()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Usuário já cadastrado");Account a=new Account();a.username=p.username().trim();a.passwordHash=encoder.encode(p.password());a.role="CLIENT";a.name=p.name();a.cpf=p.cpf();a.rg=p.rg();a.address=p.address();a.profession=p.profession();putIncomes(a,p.incomes());users.save(a);return ResponseEntity.status(201).body(profile(a));}
 private void putIncomes(Account a,List<IncomePayload> list){if(list!=null&&list.size()>3)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Máximo 3 rendimentos");a.incomes.clear();if(list!=null)for(IncomePayload p:list){Income i=new Income();i.account=a;i.employer=p.employer();i.monthlyAmount=p.monthlyAmount();a.incomes.add(i);}}
 @GetMapping("/auth/me") public Profile me(Authentication auth){return profile(current(auth));}
 @GetMapping("/clients/me") public Profile getProfile(Authentication auth){return profile(current(auth));}
 @PutMapping("/clients/me") public Profile updateProfile(Authentication auth,@RequestBody AccountPayload p){Account a=current(auth);requireClient(a);if(p.name()!=null)a.name=p.name();a.cpf=p.cpf();a.rg=p.rg();a.address=p.address();a.profession=p.profession();putIncomes(a,p.incomes());return profile(users.save(a));}
 @DeleteMapping("/clients/me") public ResponseEntity<Void> deleteProfile(Authentication auth){Account a=current(auth);requireClient(a);if(rentals.existsByClientId(a.id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Não é possível excluir cadastro com pedidos; mantenha histórico dos contratos");users.delete(a);return ResponseEntity.noContent().build();}
 @GetMapping("/clients") public List<Profile> clients(Authentication auth){if(!agent(current(auth)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return users.findAll().stream().filter(a->"CLIENT".equals(a.role)).map(this::profile).toList();}
 @GetMapping("/cars") public List<Car> cars(){return cars.findAll();}
 @GetMapping("/rentals") public List<RentalView> orders(Authentication auth){Account a=current(auth);return (agent(a)?rentals.findAllByOrderByIdDesc():rentals.findByClientIdOrderByIdDesc(a.id)).stream().map(this::view).toList();}
 private Rental ownOrAgent(Long id,Account a){Rental r=rentals.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!agent(a)&&!r.client.id.equals(a.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return r;}
 @PostMapping("/rentals") public ResponseEntity<RentalView> create(Authentication auth,@RequestBody RentalPayload p){Account a=current(auth);requireClient(a);checkDates(p.startDate(),p.endDate());Rental r=new Rental();r.client=a;r.car=cars.findById(p.carId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));r.startDate=p.startDate();r.endDate=p.endDate();return ResponseEntity.status(201).body(view(rentals.save(r)));}
 @PutMapping("/rentals/{id}") public RentalView modify(Authentication auth,@PathVariable Long id,@RequestBody RentalPayload p){Account a=current(auth);requireClient(a);Rental r=ownOrAgent(id,a);if(r.status!=Rental.Status.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Só pedidos pendentes podem ser alterados");checkDates(p.startDate(),p.endDate());r.startDate=p.startDate();r.endDate=p.endDate();return view(rentals.save(r));}
 @DeleteMapping("/rentals/{id}") public RentalView cancel(Authentication auth,@PathVariable Long id){Account a=current(auth);requireClient(a);Rental r=ownOrAgent(id,a);if(r.status!=Rental.Status.PENDING&&r.status!=Rental.Status.APPROVED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Este pedido não pode ser cancelado");r.status=Rental.Status.CANCELED;return view(rentals.save(r));}
 @PatchMapping("/rentals/{id}") public RentalView review(Authentication auth,@PathVariable Long id,@RequestBody ReviewPayload p){Account a=current(auth);if(!agent(a))throw new ResponseStatusException(HttpStatus.FORBIDDEN);Rental r=ownOrAgent(id,a);Rental.Status next;try{next=Rental.Status.valueOf(p.status());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Status inválido");}if(!(r.status==Rental.Status.PENDING&&(next==Rental.Status.APPROVED||next==Rental.Status.REJECTED)||r.status==Rental.Status.APPROVED&&next==Rental.Status.CONTRACTED))throw new ResponseStatusException(HttpStatus.CONFLICT,"Transição de estado inválida");r.status=next;r.financialOpinion=p.financialOpinion();r.reviewedBy=a.username;return view(rentals.save(r));}
 @PostMapping("/rentals/{id}/credit") public ResponseEntity<?> credit(Authentication auth,@PathVariable Long id,@RequestBody CreditPayload p){Account a=current(auth);if(!agent(a)||!"BANK".equals(a.agentType))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Restrito a agente bancário");Rental r=ownOrAgent(id,a);if(r.status!=Rental.Status.APPROVED&&r.status!=Rental.Status.CONTRACTED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Pedido precisa estar aprovado");if(r.credit!=null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Crédito já cadastrado");if(!a.id.equals(p.bankId())||p.amount()==null||p.amount().signum()<=0||p.installments()<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);CreditAgreement c=new CreditAgreement();c.bank=a;c.rental=r;c.amount=p.amount();c.installments=p.installments();credits.save(c);return ResponseEntity.status(201).body(Map.of("id",c.id,"bankId",a.id,"rentalId",r.id));}
}
